[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Leap Studio — Your Reinvention and Experience Partner</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet" />
  <style>
    /* ─── Reset & Base ─────────────────────────────── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg: #0A0A0A;
      --bg2: #111111;
      --bg3: #1A1A1A;
      --border: rgba(255,255,255,0.08);
      --white: #FFFFFF;
      --gray: #808080;
      --gray-light: #AAAAAA;
      --accent: #3B7FFF;
      --accent-hover: #5A95FF;
      --amber: #F5A623;
      --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      --nav-h: 72px;
      --radius: 4px;
      --transition: 0.3s ease;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font);
      background: var(--bg);
      color: var(--white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    a { color: inherit; text-decoration: none; }
    button { cursor: pointer; font-family: var(--font); border: none; background: none; }
    img { display: block; }

    /* ─── Utility ──────────────────────────────────── */
    .container { max-width: 1280px; margin: 0 auto; padding: 0 40px; }
    @media (max-width: 768px) { .container { padding: 0 20px; } }

    .btn {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 12px 28px;
      border: 1px solid var(--white);
      color: var(--white);
      font-size: 14px;
      font-weight: 500;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      transition: background var(--transition), color var(--transition);
      border-radius: var(--radius);
    }
    .btn:hover { background: var(--white); color: var(--bg); }

    .btn-primary {
      background: var(--accent);
      border-color: var(--accent);
    }
    .btn-primary:hover { background: var(--accent-hover); border-color: var(--accent-hover); color: var(--white); }

    .section-label {
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.15em;
      text-transform: uppercase;
      color: var(--gray);
      margin-bottom: 16px;
    }

    .section-title {
      font-size: clamp(28px, 4vw, 48px);
      font-weight: 700;
      line-height: 1.15;
      letter-spacing: -0.02em;
    }

    .section-subtitle {
      font-size: 17px;
      color: var(--gray-light);
      max-width: 600px;
      margin-top: 12px;
      line-height: 1.65;
    }

    /* ─── Nav ──────────────────────────────────────── */
    .nav {
      position: fixed;
      top: 0; left: 0; right: 0;
      height: var(--nav-h);
      z-index: 1000;
      display: flex;
      align-items: center;
      background: rgba(10,10,10,0.85);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid var(--border);
      transition: background var(--transition);
    }

    .nav-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      width: 100%;
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 40px;
    }

    .nav-logo {
      font-size: 20px;
      font-weight: 800;
      letter-spacing: -0.03em;
      color: var(--white);
      display: flex;
      align-items: center;
      gap: 10px;
    }
    .nav-logo-mark {
      width: 32px; height: 32px;
      background: var(--accent);
      border-radius: 6px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 16px;
      font-weight: 900;
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 32px;
      list-style: none;
    }
    .nav-links a {
      font-size: 14px;
      font-weight: 500;
      color: var(--gray-light);
      letter-spacing: 0.01em;
      transition: color var(--transition);
    }
    .nav-links a:hover { color: var(--white); }

    .nav-right {
      display: flex;
      align-items: center;
      gap: 20px;
    }

    /* Language selector */
    .lang-selector {
      position: relative;
    }
    .lang-btn {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 13px;
      font-weight: 500;
      color: var(--gray-light);
      padding: 6px 10px;
      border: 1px solid var(--border);
      border-radius: var(--radius);
      transition: color var(--transition), border-color var(--transition);
    }
    .lang-btn:hover { color: var(--white); border-color: rgba(255,255,255,0.25); }
    .lang-btn svg { transition: transform var(--transition); }
    .lang-btn.open svg { transform: rotate(180deg); }

    .lang-dropdown {
      position: absolute;
      top: calc(100% + 8px);
      right: 0;
      background: var(--bg3);
      border: 1px solid var(--border);
      border-radius: 6px;
      min-width: 160px;
      overflow: hidden;
      opacity: 0;
      pointer-events: none;
      transform: translateY(-8px);
      transition: opacity var(--transition), transform var(--transition);
    }
    .lang-dropdown.open {
      opacity: 1;
      pointer-events: auto;
      transform: translateY(0);
    }
    .lang-dropdown a {
      display: block;
      padding: 12px 16px;
      font-size: 14px;
      color: var(--gray-light);
      transition: background var(--transition), color var(--transition);
    }
    .lang-dropdown a:hover { background: rgba(255,255,255,0.05); color: var(--white); }
    .lang-dropdown a.active { color: var(--white); background: rgba(59,127,255,0.12); }

    .nav-cta {
      padding: 9px 20px;
      font-size: 13px;
    }

    /* Mobile hamburger */
    .nav-toggle {
      display: none;
      flex-direction: column;
      gap: 5px;
      padding: 8px;
    }
    .nav-toggle span {
      width: 22px; height: 2px;
      background: var(--white);
      border-radius: 2px;
      transition: transform var(--transition), opacity var(--transition);
    }
    .nav-toggle.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
    .nav-toggle.open span:nth-child(2) { opacity: 0; }
    .nav-toggle.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

    .mobile-menu {
      display: none;
      position: fixed;
      top: var(--nav-h);
      left: 0; right: 0; bottom: 0;
      background: var(--bg);
      z-index: 999;
      flex-direction: column;
      padding: 32px 24px;
      gap: 24px;
      overflow-y: auto;
    }
    .mobile-menu.open { display: flex; }
    .mobile-menu a {
      font-size: 22px;
      font-weight: 600;
      color: var(--gray-light);
      padding: 8px 0;
      border-bottom: 1px solid var(--border);
      transition: color var(--transition);
    }
    .mobile-menu a:hover { color: var(--white); }

    @media (max-width: 1024px) {
      .nav-links { display: none; }
      .nav-toggle { display: flex; }
    }
    @media (max-width: 768px) {
      .nav-inner { padding: 0 20px; }
      .nav-cta { display: none; }
    }

    /* ─── Hero ─────────────────────────────────────── */
    .hero {
      position: relative;
      height: 100vh;
      min-height: 600px;
      overflow: hidden;
      display: flex;
      align-items: flex-end;
    }

    .hero-slides {
      position: absolute;
      inset: 0;
    }

    .hero-slide {
      position: absolute;
      inset: 0;
      opacity: 0;
      transition: opacity 0.9s ease;
      display: flex;
      align-items: flex-end;
    }
    .hero-slide.active { opacity: 1; }

    .hero-bg {
      position: absolute;
      inset: 0;
      background-size: cover;
      background-position: center;
      transform: scale(1.05);
      transition: transform 8s ease;
    }
    .hero-slide.active .hero-bg { transform: scale(1); }

    .hero-bg-1 { background: linear-gradient(135deg, #0A1628 0%, #162A4A 40%, #0D1F3C 100%); }
    .hero-bg-2 { background: linear-gradient(135deg, #0F0F1A 0%, #1A1028 40%, #0A0A15 100%); }
    .hero-bg-3 { background: linear-gradient(135deg, #051A15 0%, #0A2E24 40%, #041510 100%); }
    .hero-bg-4 { background: linear-gradient(135deg, #1A0A0A 0%, #2E1010 40%, #180808 100%); }
    .hero-bg-5 { background: linear-gradient(135deg, #0F1A0A 0%, #1E2E10 40%, #0C1808 100%); }

    .hero-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(10,10,10,0.92) 0%, rgba(10,10,10,0.4) 50%, rgba(10,10,10,0.1) 100%);
    }

    .hero-grid {
      position: absolute;
      inset: 0;
      background-image: linear-gradient(rgba(59,127,255,0.04) 1px, transparent 1px),
                        linear-gradient(90deg, rgba(59,127,255,0.04) 1px, transparent 1px);
      background-size: 64px 64px;
    }

    .hero-content {
      position: relative;
      z-index: 2;
      width: 100%;
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 40px 100px;
    }

    .hero-slide-content {
      max-width: 680px;
    }

    .hero-tag {
      display: inline-block;
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.15em;
      text-transform: uppercase;
      color: var(--accent);
      margin-bottom: 20px;
      padding: 4px 10px;
      border: 1px solid rgba(59,127,255,0.3);
      border-radius: 2px;
      background: rgba(59,127,255,0.08);
    }

    .hero-title {
      font-size: clamp(36px, 5.5vw, 76px);
      font-weight: 800;
      line-height: 1.06;
      letter-spacing: -0.03em;
      margin-bottom: 20px;
    }

    .hero-desc {
      font-size: clamp(15px, 1.6vw, 18px);
      color: rgba(255,255,255,0.75);
      line-height: 1.7;
      margin-bottom: 32px;
      max-width: 520px;
    }

    /* Hero nav */
    .hero-nav {
      position: absolute;
      bottom: 44px;
      right: 40px;
      z-index: 3;
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .hero-nav-dots {
      display: flex;
      gap: 8px;
    }
    .hero-dot {
      width: 28px; height: 3px;
      background: rgba(255,255,255,0.25);
      border-radius: 2px;
      cursor: pointer;
      transition: background var(--transition), width var(--transition);
    }
    .hero-dot.active {
      background: var(--white);
      width: 40px;
    }

    .hero-nav-btns {
      display: flex;
      gap: 8px;
    }

    .hero-arrow {
      width: 44px; height: 44px;
      border: 1px solid rgba(255,255,255,0.2);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--white);
      transition: background var(--transition), border-color var(--transition);
    }
    .hero-arrow:hover { background: rgba(255,255,255,0.1); border-color: rgba(255,255,255,0.4); }

    .hero-counter {
      position: absolute;
      bottom: 52px;
      left: 40px;
      z-index: 3;
      font-size: 12px;
      color: var(--gray);
      letter-spacing: 0.08em;
    }

    @media (max-width: 768px) {
      .hero-content { padding: 0 20px 120px; }
      .hero-nav { right: 20px; }
      .hero-counter { left: 20px; }
    }

    /* ─── Section spacing ──────────────────────────── */
    .section { padding: 100px 0; }
    .section-header { margin-bottom: 56px; }
    @media (max-width: 768px) { .section { padding: 64px 0; } .section-header { margin-bottom: 40px; } }

    /* ─── Team / Region Toggle ─────────────────────── */
    .team-section { background: var(--bg); overflow: hidden; }

    .region-tabs {
      display: flex;
      gap: 0;
      border-bottom: 1px solid var(--border);
      margin-bottom: 56px;
      overflow-x: auto;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
    }
    .region-tabs::-webkit-scrollbar { display: none; }

    .region-tab {
      flex-shrink: 0;
      padding: 14px 28px;
      font-size: 14px;
      font-weight: 500;
      color: var(--gray);
      border-bottom: 2px solid transparent;
      margin-bottom: -1px;
      transition: color var(--transition), border-color var(--transition);
      white-space: nowrap;
    }
    .region-tab:hover { color: var(--white); }
    .region-tab.active {
      color: var(--white);
      border-bottom-color: var(--accent);
    }

    /* Team carousel */
    .team-carousel-wrapper {
      position: relative;
      overflow: hidden;
    }

    .team-region {
      display: none;
    }
    .team-region.active { display: block; }

    .team-track {
      display: flex;
      gap: 24px;
      transition: transform 0.5s ease;
    }

    .team-card {
      flex: 0 0 calc(33.33% - 16px);
      background: var(--bg3);
      border: 1px solid var(--border);
      border-radius: 8px;
      overflow: hidden;
      transition: border-color var(--transition), transform var(--transition);
    }
    .team-card:hover { border-color: rgba(255,255,255,0.2); transform: translateY(-4px); }

    .team-card-img {
      width: 100%;
      aspect-ratio: 3/2;
      background: var(--bg2);
      position: relative;
      overflow: hidden;
    }

    .team-avatar {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 52px;
      font-weight: 700;
      color: rgba(255,255,255,0.12);
      position: relative;
    }

    .team-avatar-bg-1 { background: linear-gradient(135deg, #0D1F3C, #162A4A); }
    .team-avatar-bg-2 { background: linear-gradient(135deg, #1A1028, #2A1840); }
    .team-avatar-bg-3 { background: linear-gradient(135deg, #0A2E24, #0F3D30); }
    .team-avatar-bg-4 { background: linear-gradient(135deg, #2E1010, #3D1A1A); }
    .team-avatar-bg-5 { background: linear-gradient(135deg, #1E2E10, #2A3E18); }
    .team-avatar-bg-6 { background: linear-gradient(135deg, #1A180A, #2A2710); }
    .team-avatar-bg-7 { background: linear-gradient(135deg, #0A1A2E, #10253D); }

    .team-initials {
      position: absolute;
      bottom: 16px;
      left: 16px;
      width: 48px; height: 48px;
      border-radius: 50%;
      background: rgba(255,255,255,0.1);
      border: 1px solid rgba(255,255,255,0.15);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 16px;
      font-weight: 700;
      color: var(--white);
    }

    .team-card-body {
      padding: 24px;
    }

    .team-card-name {
      font-size: 18px;
      font-weight: 700;
      margin-bottom: 2px;
    }

    .team-card-title {
      font-size: 13px;
      color: var(--accent);
      font-weight: 500;
      margin-bottom: 4px;
    }

    .team-card-office {
      font-size: 13px;
      color: var(--gray);
      display: flex;
      align-items: center;
      gap: 4px;
      margin-bottom: 16px;
    }

    .team-card-quote {
      font-size: 14px;
      color: var(--gray-light);
      line-height: 1.65;
      font-style: italic;
      margin-bottom: 20px;
      padding-left: 12px;
      border-left: 2px solid var(--accent);
    }

    .team-card-cta {
      font-size: 12px;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--accent);
      display: flex;
      align-items: center;
      gap: 6px;
      transition: gap var(--transition);
    }
    .team-card-cta:hover { gap: 10px; }

    .team-carousel-controls {
      display: flex;
      align-items: center;
      justify-content: flex-end;
      gap: 12px;
      margin-top: 32px;
    }

    .carousel-arrow {
      width: 44px; height: 44px;
      border: 1px solid var(--border);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--white);
      transition: background var(--transition), border-color var(--transition);
    }
    .carousel-arrow:hover { background: rgba(255,255,255,0.06); border-color: rgba(255,255,255,0.2); }
    .carousel-arrow:disabled { opacity: 0.3; cursor: default; }

    .carousel-progress {
      font-size: 13px;
      color: var(--gray);
      letter-spacing: 0.08em;
      margin-right: auto;
    }

    @media (max-width: 1024px) {
      .team-card { flex: 0 0 calc(50% - 12px); }
    }
    @media (max-width: 640px) {
      .team-card { flex: 0 0 85%; }
    }

    /* ─── Work Showcase ────────────────────────────── */
    .work-section { background: var(--bg2); overflow: hidden; }

    .work-scroll-container {
      position: relative;
    }

    .work-track {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      -webkit-overflow-scrolling: touch;
      scroll-snap-type: x mandatory;
      scrollbar-width: none;
      padding-bottom: 4px;
      cursor: grab;
    }
    .work-track::-webkit-scrollbar { display: none; }
    .work-track.grabbing { cursor: grabbing; }

    .work-card {
      flex: 0 0 380px;
      scroll-snap-align: start;
      background: var(--bg3);
      border: 1px solid var(--border);
      border-radius: 8px;
      overflow: hidden;
      transition: border-color var(--transition), transform var(--transition);
    }
    .work-card:hover { border-color: rgba(255,255,255,0.18); transform: translateY(-4px); }

    .work-card-thumb {
      width: 100%;
      aspect-ratio: 16/9;
      background: var(--bg2);
      position: relative;
      overflow: hidden;
    }

    .work-thumb-inner {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
    }

    .work-thumb-bg-1 { background: linear-gradient(135deg, #0D2B4A 0%, #1A4A7A 100%); }
    .work-thumb-bg-2 { background: linear-gradient(135deg, #1A0D2B 0%, #2E1A4A 100%); }
    .work-thumb-bg-3 { background: linear-gradient(135deg, #0D1A2B 0%, #1A2E4A 100%); }
    .work-thumb-bg-4 { background: linear-gradient(135deg, #2B1A0D 0%, #4A3018 100%); }
    .work-thumb-bg-5 { background: linear-gradient(135deg, #2B0D1A 0%, #4A1A2E 100%); }
    .work-thumb-bg-6 { background: linear-gradient(135deg, #0D2B1A 0%, #1A4A30 100%); }
    .work-thumb-bg-7 { background: linear-gradient(135deg, #1A1A2B 0%, #2B2B4A 100%); }
    .work-thumb-bg-8 { background: linear-gradient(135deg, #2B1A1A 0%, #4A2B2B 100%); }

    .work-thumb-logo {
      font-size: 15px;
      font-weight: 700;
      color: rgba(255,255,255,0.25);
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .work-thumb-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(to bottom, transparent 50%, rgba(10,10,10,0.6) 100%);
    }

    .work-card-body {
      padding: 24px;
    }

    .work-card-client {
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--accent);
      margin-bottom: 8px;
    }

    .work-card-title {
      font-size: 18px;
      font-weight: 700;
      line-height: 1.3;
      margin-bottom: 12px;
      letter-spacing: -0.01em;
    }

    .work-card-quote {
      font-size: 13px;
      color: var(--gray-light);
      line-height: 1.6;
      font-style: italic;
      margin-bottom: 8px;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .work-card-attribution {
      font-size: 12px;
      color: var(--gray);
      margin-bottom: 20px;
    }

    .work-card-link {
      font-size: 12px;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--white);
      display: flex;
      align-items: center;
      gap: 8px;
      transition: color var(--transition), gap var(--transition);
    }
    .work-card-link:hover { color: var(--accent); gap: 12px; }

    .work-scroll-controls {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-top: 32px;
    }

    .work-scroll-hint {
      font-size: 13px;
      color: var(--gray);
    }

    .work-nav-btns {
      display: flex;
      gap: 12px;
    }

    /* ─── CTA Banner ───────────────────────────────── */
    .cta-banner {
      background: var(--accent);
      padding: 80px 0;
    }

    .cta-banner-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 40px;
      flex-wrap: wrap;
    }

    .cta-banner-text {}

    .cta-banner-title {
      font-size: clamp(28px, 3.5vw, 44px);
      font-weight: 800;
      letter-spacing: -0.02em;
      line-height: 1.1;
      margin-bottom: 12px;
    }

    .cta-banner-body {
      font-size: 16px;
      color: rgba(255,255,255,0.82);
      max-width: 540px;
      line-height: 1.65;
    }

    .cta-banner .btn {
      border-color: var(--white);
      white-space: nowrap;
      flex-shrink: 0;
    }
    .cta-banner .btn:hover { background: var(--white); color: var(--accent); }

    /* ─── How We Work ──────────────────────────────── */
    .how-section {
      background: var(--bg);
      overflow: hidden;
    }

    .how-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }

    .how-visual {
      position: relative;
      border-radius: 12px;
      overflow: hidden;
      aspect-ratio: 4/3;
      background: var(--bg3);
      border: 1px solid var(--border);
    }

    .how-visual-pattern {
      position: absolute;
      inset: 0;
      background-image:
        radial-gradient(circle at 30% 40%, rgba(59,127,255,0.15) 0%, transparent 50%),
        radial-gradient(circle at 70% 70%, rgba(245,166,35,0.08) 0%, transparent 40%),
        linear-gradient(rgba(59,127,255,0.03) 1px, transparent 1px),
        linear-gradient(90deg, rgba(59,127,255,0.03) 1px, transparent 1px);
      background-size: auto, auto, 48px 48px, 48px 48px;
    }

    .how-visual-content {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-direction: column;
      gap: 24px;
      padding: 40px;
      text-align: center;
    }

    .how-visual-stat {
      font-size: 64px;
      font-weight: 900;
      letter-spacing: -0.04em;
      color: var(--white);
      line-height: 1;
    }

    .how-visual-stat span {
      font-size: 32px;
      color: var(--accent);
    }

    .how-visual-label {
      font-size: 13px;
      color: var(--gray);
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }

    .how-divider {
      width: 60px;
      height: 1px;
      background: var(--border);
    }

    .how-headline {
      font-size: clamp(28px, 3.5vw, 44px);
      font-weight: 800;
      letter-spacing: -0.02em;
      line-height: 1.15;
      margin-bottom: 20px;
    }

    .how-body {
      font-size: 16px;
      color: var(--gray-light);
      line-height: 1.75;
      margin-bottom: 32px;
    }

    @media (max-width: 900px) {
      .how-inner { grid-template-columns: 1fr; gap: 40px; }
      .how-visual { max-width: 500px; }
    }

    /* ─── Insights ─────────────────────────────────── */
    .insights-section { background: var(--bg2); }

    .insights-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1px;
      background: var(--border);
      border: 1px solid var(--border);
      border-radius: 8px;
      overflow: hidden;
    }

    .insight-card {
      background: var(--bg2);
      padding: 28px;
      transition: background var(--transition);
    }
    .insight-card:hover { background: var(--bg3); }

    .insight-type-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 10px;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--gray);
      margin-bottom: 12px;
    }
    .insight-type-badge.podcast { color: #A78BFA; }
    .insight-type-badge.article { color: var(--accent); }
    .insight-type-badge.report { color: var(--amber); }

    .insight-icon {
      width: 28px; height: 28px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 12px;
    }
    .insight-icon.podcast { background: rgba(167,139,250,0.15); }
    .insight-icon.article { background: rgba(59,127,255,0.15); }
    .insight-icon.report { background: rgba(245,166,35,0.15); }

    .insight-thumb {
      width: 100%;
      aspect-ratio: 16/9;
      border-radius: 4px;
      margin-bottom: 16px;
      overflow: hidden;
    }

    .insight-thumb-inner {
      width: 100%;
      height: 100%;
    }

    .insight-thumb-bg-1 { background: linear-gradient(135deg, #1A1028, #0D0A1A); }
    .insight-thumb-bg-2 { background: linear-gradient(135deg, #0D1A28, #081018); }
    .insight-thumb-bg-3 { background: linear-gradient(135deg, #051A15, #0A2E24); }
    .insight-thumb-bg-4 { background: linear-gradient(135deg, #1A0D28, #280D3A); }
    .insight-thumb-bg-5 { background: linear-gradient(135deg, #0D1A10, #1A2E14); }
    .insight-thumb-bg-6 { background: linear-gradient(135deg, #1A180A, #2A2714); }
    .insight-thumb-bg-7 { background: linear-gradient(135deg, #0A1A2E, #10253D); }
    .insight-thumb-bg-8 { background: linear-gradient(135deg, #1A0D10, #2A1015); }

    .insight-title {
      font-size: 15px;
      font-weight: 600;
      line-height: 1.4;
      margin-bottom: 16px;
      color: var(--white);
    }

    .insight-cta {
      font-size: 12px;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      display: flex;
      align-items: center;
      gap: 6px;
      transition: gap var(--transition);
    }
    .insight-cta.podcast { color: #A78BFA; }
    .insight-cta.article { color: var(--accent); }
    .insight-cta.report { color: var(--amber); }
    .insight-cta:hover { gap: 10px; }

    @media (max-width: 1024px) {
      .insights-grid { grid-template-columns: repeat(2, 1fr); }
    }
    @media (max-width: 640px) {
      .insights-grid { grid-template-columns: 1fr; }
    }

    /* ─── Principles ───────────────────────────────── */
    .principles-section { background: var(--bg); }

    .principles-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 1px;
      background: var(--border);
      border: 1px solid var(--border);
      border-radius: 8px;
      overflow: hidden;
    }

    .principle-card {
      background: var(--bg);
      padding: 48px;
      position: relative;
      overflow: hidden;
      transition: background var(--transition);
    }
    .principle-card:hover { background: var(--bg3); }

    .principle-number {
      font-size: 80px;
      font-weight: 900;
      color: rgba(255,255,255,0.03);
      position: absolute;
      top: 16px;
      right: 24px;
      line-height: 1;
      letter-spacing: -0.04em;
    }

    .principle-icon {
      width: 48px; height: 48px;
      border-radius: 10px;
      background: rgba(59,127,255,0.1);
      border: 1px solid rgba(59,127,255,0.2);
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 24px;
      font-size: 20px;
    }

    .principle-title {
      font-size: 20px;
      font-weight: 700;
      letter-spacing: -0.01em;
      margin-bottom: 14px;
    }

    .principle-body {
      font-size: 15px;
      color: var(--gray-light);
      line-height: 1.7;
    }

    @media (max-width: 768px) {
      .principles-grid { grid-template-columns: 1fr; }
      .principle-card { padding: 32px 24px; }
    }

    /* ─── Footer ───────────────────────────────────── */
    .footer {
      background: var(--bg2);
      border-top: 1px solid var(--border);
      padding: 80px 0 40px;
    }

    .footer-ctas {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1px;
      background: var(--border);
      border: 1px solid var(--border);
      border-radius: 8px;
      overflow: hidden;
      margin-bottom: 64px;
    }

    .footer-cta-card {
      background: var(--bg2);
      padding: 48px;
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      gap: 32px;
      transition: background var(--transition);
    }
    .footer-cta-card:hover { background: var(--bg3); }

    .footer-cta-text p {
      font-size: 18px;
      color: var(--gray-light);
      line-height: 1.65;
      max-width: 380px;
    }

    .footer-bottom {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 40px;
      flex-wrap: wrap;
    }

    .footer-brand {
      display: flex;
      flex-direction: column;
      gap: 16px;
    }

    .footer-logo {
      font-size: 22px;
      font-weight: 800;
      letter-spacing: -0.03em;
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .footer-tagline {
      font-size: 13px;
      color: var(--gray);
      max-width: 260px;
      line-height: 1.6;
    }

    .footer-links-group {
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .footer-links-title {
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--gray);
      margin-bottom: 4px;
    }

    .footer-links-group a {
      font-size: 14px;
      color: var(--gray-light);
      transition: color var(--transition);
    }
    .footer-links-group a:hover { color: var(--white); }

    .footer-legal {
      border-top: 1px solid var(--border);
      margin-top: 48px;
      padding-top: 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
      flex-wrap: wrap;
    }

    .footer-legal p {
      font-size: 13px;
      color: var(--gray);
    }

    .footer-legal-links {
      display: flex;
      gap: 20px;
    }

    .footer-legal-links a {
      font-size: 13px;
      color: var(--gray);
      transition: color var(--transition);
    }
    .footer-legal-links a:hover { color: var(--white); }

    @media (max-width: 768px) {
      .footer-ctas { grid-template-columns: 1fr; }
      .footer-cta-card { flex-direction: column; align-items: flex-start; padding: 32px 24px; }
      .footer-bottom { flex-direction: column; }
      .footer-legal { flex-direction: column; align-items: flex-start; }
    }

    /* ─── Cookie Banner ────────────────────────────── */
    .cookie-banner {
      position: fixed;
      bottom: 0; left: 0; right: 0;
      z-index: 2000;
      background: var(--bg3);
      border-top: 1px solid var(--border);
      padding: 20px 40px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
      flex-wrap: wrap;
      transform: translateY(0);
      transition: transform 0.4s ease;
    }
    .cookie-banner.hidden { transform: translateY(100%); }

    .cookie-text {
      font-size: 14px;
      color: var(--gray-light);
      max-width: 640px;
      line-height: 1.55;
    }
    .cookie-text a { color: var(--accent); text-decoration: underline; }

    .cookie-actions {
      display: flex;
      gap: 12px;
      flex-wrap: wrap;
    }

    .cookie-btn {
      padding: 9px 20px;
      font-size: 13px;
      font-weight: 500;
      border-radius: var(--radius);
      transition: background var(--transition), color var(--transition), border-color var(--transition);
    }
    .cookie-btn-accept {
      background: var(--accent);
      color: var(--white);
      border: 1px solid var(--accent);
    }
    .cookie-btn-accept:hover { background: var(--accent-hover); }
    .cookie-btn-decline {
      border: 1px solid var(--border);
      color: var(--gray-light);
    }
    .cookie-btn-decline:hover { border-color: rgba(255,255,255,0.2); color: var(--white); }
    .cookie-btn-manage {
      border: 1px solid transparent;
      color: var(--gray);
      font-size: 13px;
      padding: 9px 0;
    }
    .cookie-btn-manage:hover { color: var(--white); }

    @media (max-width: 768px) {
      .cookie-banner { padding: 20px; }
      .cookie-actions { width: 100%; }
    }

    /* ─── Scroll fade-in ───────────────────────────── */
    .fade-in {
      opacity: 0;
      transform: translateY(24px);
      transition: opacity 0.6s ease, transform 0.6s ease;
    }
    .fade-in.visible {
      opacity: 1;
      transform: none;
    }
    .fade-in-delay-1 { transition-delay: 0.1s; }
    .fade-in-delay-2 { transition-delay: 0.2s; }
    .fade-in-delay-3 { transition-delay: 0.3s; }

    /* Arrow SVG */
    .arrow-icon {
      width: 16px; height: 16px;
      fill: none;
      stroke: currentColor;
      stroke-width: 2;
      stroke-linecap: round;
      stroke-linejoin: round;
    }
  </style>
</head>
