from html.parser import HTMLParser
class V(HTMLParser):
    def __init__(self):
        super().__init__()
        self.errors = []
        self.stack = []
        self.void = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
    def handle_starttag(self, tag, attrs):
        if tag not in self.void: self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag in self.void: return
        if self.stack and self.stack[-1] == tag: self.stack.pop()
        else: self.errors.append(f'Unmatched </{tag}>, stack top: {self.stack[-1] if self.stack else \"empty\"}')

with open('/app/output/index.html') as f:
    content = f.read()

v = V()
v.feed(content)
if v.errors:
    for e in v.errors[:5]: print('ERROR:', e)
elif v.stack:
    print('Unclosed tags:', v.stack[-5:])
else:
    print('HTML structure OK')
